function parseCsvLine(line) {
  const fields = [];
  let value = "", quoted = false;
  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    if (char === '"') {
      if (quoted && line[i + 1] === '"') { value += '"'; i += 1; }
      else quoted = !quoted;
    } else if (char === "," && !quoted) { fields.push(value); value = ""; }
    else value += char;
  }
  fields.push(value);
  return fields;
}

function readCsv(filePath) {
  const lines = fs.readFileSync(filePath, "utf8").split(/\r?\n/).filter(Boolean);
  const headers = parseCsvLine(lines.shift());
  return lines.map(line => Object.fromEntries(parseCsvLine(line).map((value, index) => [headers[index], value])));
}

function num(value) { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : null; }
function sum(values) { return values.reduce((total, value) => total + value, 0); }
function mean(values) { return values.length ? sum(values) / values.length : null; }
function stddev(values) { const center = mean(values); return center == null ? null : Math.sqrt(mean(values.map(value => (value - center) ** 2))); }
function median(values) { if (!values.length) return null; const sorted = [...values].sort((a,b)=>a-b), middle = Math.floor(sorted.length / 2); return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2; }
function quantile(values, probability) { if (!values.length) return null; const sorted=[...values].sort((a,b)=>a-b), index=(sorted.length-1)*probability, low=Math.floor(index), high=Math.ceil(index); return low===high?sorted[low]:sorted[low]+(sorted[high]-sorted[low])*(index-low); }
function correlation(rows, xFn, yFn) {
  const pairs = rows.map(row => [num(xFn(row)), num(yFn(row))]).filter(([x,y]) => x != null && y != null);
  if (pairs.length < 2) return null;
  const mx=mean(pairs.map(x=>x[0])), my=mean(pairs.map(x=>x[1]));
  const numerator=sum(pairs.map(([x,y])=>(x-mx)*(y-my))), dx=Math.sqrt(sum(pairs.map(([x])=>(x-mx)**2))), dy=Math.sqrt(sum(pairs.map(([,y])=>(y-my)**2)));
  return dx && dy ? numerator/(dx*dy) : null;
}
function normalizeName(value) { return String(value||"").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/\b(jr|sr|ii|iii|iv)\b/g,"").replace(/[^a-z0-9]/g,""); }
function normalizeTeam(value) { return ({JAC:"JAX",LA:"LAR",OAK:"LV",SD:"LAC",STL:"LAR",WSH:"WAS"}[value]||value); }
function sha256File(filePath) { return crypto.createHash("sha256").update(fs.readFileSync(filePath)).digest("hex"); }
function csvCell(value) { return `"${String(value??"").replaceAll('"','""')}"`; }
function csv(rows, headers) { return [headers.join(","), ...rows.map(row => headers.map(header => csvCell(row[header])).join(","))].join("\n")+"\n"; }
function round(value, digits=4) { return value == null ? null : Number(value.toFixed(digits)); }

function adpPosition(value) {
  const match = String(value||"").match(/^([A-Z/]+)/);
  const raw = match?.[1] || "";
  return raw === "DST" ? "D/ST" : raw;
}

function loadAdpEnvironment(filePath) {
  const raw = readCsv(filePath).map(row => ({
    sourceRank: num(row.Rank), name: row.Player, position: adpPosition(row.POS), nflTeam: normalizeTeam(row.Team), bye: num(row.Bye), planningAdp: num(row.AVG) ?? num(row.Rank),
  })).filter(row => TARGET_POSITIONS.has(row.position) && row.name && row.planningAdp != null);
  raw.sort((a,b)=>a.planningAdp-b.planningAdp||a.sourceRank-b.sourceRank||a.name.localeCompare(b.name));
  const positionRanks = {};
  const allPlayers = raw.map((row,index) => {
    positionRanks[row.position]=(positionRanks[row.position]||0)+1;
    const nflTeam = row.position === "D/ST" ? DST_NAMES[row.name] : row.nflTeam;
    return {
      id:`bt25_${index+1}`, name:row.name, position:row.position, nfl_team:nflTeam||"", bye:String(row.bye??""), rank:String(index+1),
      position_rank:String(positionRanks[row.position]), adp:String(row.planningAdp), planning_adp:String(row.planningAdp), consensus_adp:String(row.planningAdp),
      projected_points:"", projection_status:"UNAVAILABLE_NEUTRAL", breakout_score:"50", breakout_source:"UNAVAILABLE_NEUTRAL", bust_score:"50",
      environment_score:"50", intrinsic_source:"2025_MARKET_ONLY", intrinsic_confidence:"35", model_coverage:"2025_ADP_ONLY",
      situation_score:"50", situation_confidence:"0", availability_status:"PRE_DRAFT_OUTCOME_BLIND", situation_summary:"Historical role context unavailable; neutralized.",
      depth_role:"", role_score:"50", health_score:"50", offense_context_score:"50", competition_score:"50", situation_as_of:"2025-08-21",
      situation_source:"UNAVAILABLE_NEUTRAL", market_confidence:"MEDIUM", market_summary:"Archived 2025 consensus ADP snapshot.", market_as_of:"2025-08-21",
      tier:"", tier_method:"UNAVAILABLE_NEUTRAL", contingent_score:"50", contingent_source:"UNAVAILABLE_NEUTRAL", notes:"Analysis-only 2025 reconstruction", drafted:false,
    };
  });
  const neutralPool = allPlayers.slice(0,331).map(player=>structuredClone(player));
  const proxyPool = neutralPool.map(player=>({...structuredClone(player),tier:String(Math.floor((Number(player.position_rank)-1)/6)+1),tier_method:"POSITION_ADP_BAND_6_SENSITIVITY_PROXY"}));
  return { rawRows:raw, allPlayers, neutralPool, proxyPool };
}

function modelSource() {
  const html = zlib.gunzipSync(fs.readFileSync("app.html.gz")).toString("utf8");
  const start=html.indexOf("const ROUND_ORDER="), end=html.indexOf("function renderRosters",start);
  if(start<0||end<0) throw new Error("Could not isolate production model source");
  return html.slice(start,end);
}

